(()=>{const s='https://open.spotify.com/embed/show/4NluRPjuAIGK59vVf7GcoF';document.addEventListener('click',e=>{const b=e.target.closest('[data-spotify-load]');if(!b)return;const w=b.closest('[data-spotify-facade]');if(!w)return;const f=document.createElement('iframe');f.title="Turing's Torch on Spotify";f.src=s;f.loading='lazy';f.allow='autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture';w.replaceChildren(f)})})();
